package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.hardware.CRServo;
import com.qualcomm.robotcore.hardware.HardwareMap;

import org.firstinspires.ftc.teamcode.config.DeviceNames;
import org.firstinspires.ftc.teamcode.config.Tuned;

// Generated by refract-suite ftc-construct. FLOWER-bottom POLLEN retrieval ramp, let out and pulled back up by strings
// on two continuous rotation servos (team 2026-10-17); the second is mounted mirrored, so it gets the opposite power.
// The strings keep tension and the ramp rests up by itself, so between runs the servos are stopped. Nothing reports
// where the ramp is: it runs at RAMP_POWER for the times program 4 measured (rampOutS out, rampInS in), and its place
// is a share from 0 (stowed) to 1 (out) moved at that rate. A command part way turns it back from where it is. Never
// powered in INIT (R102). Call update() every loop.
public class Ramp {
    // operating power, not a measurement: the times are measured at it
    public static double RAMP_POWER = 1.0;
    // set by program 2: true if +power on the left servo lets the ramp OUT
    public static boolean RAMP_REVERSED = false;

    private final CRServo left, right;
    private boolean out = false;
    private double share = 0;
    private long lastNanos = 0;

    public Ramp(HardwareMap hardwareMap) {
        left = hardwareMap.get(CRServo.class, DeviceNames.RAMP_LEFT);
        right = hardwareMap.get(CRServo.class, DeviceNames.RAMP_RIGHT);
    }

    public static boolean calibrated() {
        return Tuned.isSet(Tuned.rampOutS, Tuned.rampInS) && Tuned.rampOutS > 0 && Tuned.rampInS > 0;
    }

    public boolean toggle() {
        return set(!out);
    }

    // Starts the ramp moving out or in; false (nothing moves) until program 4 timed it
    public boolean set(boolean deploy) {
        if (!calibrated()) return false;
        out = deploy;
        return true;
    }

    // Moves the share toward the command at the timed rate and powers the servos for it
    public void update() {
        long now = System.nanoTime();
        double dt = lastNanos == 0 ? 0 : Math.min(0.1, (now - lastNanos) / 1e9);
        lastNanos = now;
        if (!calibrated()) {
            drive(0);
            return;
        }
        if (out && share < 1) {
            share = Math.min(1, share + dt / Tuned.rampOutS);
            drive(RAMP_POWER);
        } else if (!out && share > 0) {
            share = Math.max(0, share - dt / Tuned.rampInS);
            drive(-RAMP_POWER);
        } else {
            drive(0);
        }
    }

    // both servos at this power, + = out (the setup programs drive it directly; the match uses set / update)
    public void drive(double p) {
        double l = RAMP_REVERSED ? -p : p;
        left.setPower(l);
        right.setPower(-l);
    }

    public void stop() {
        drive(0);
    }

    // fully out (the timed run has finished)
    public boolean deployed() {
        return out && share >= 1;
    }

    // commanded out (it may still be on its way)
    public boolean commandedOut() {
        return out;
    }

    // 0 = stowed, 1 = out
    public double share() {
        return share;
    }
}
